<style scoped>
.marker {
  --seek-accent: var(--k-accent);
  --seek-fur: #d3bc5f;
  display: block;
  overflow: visible;
}
.f-accent { fill: var(--seek-accent); }
.f-accent-dark { fill: color-mix(in oklab, var(--seek-accent), black 20%); }
.s-accent-dark { stroke: color-mix(in oklab, var(--seek-accent), black 20%); }
.f-game { fill: var(--seek-fur); }
.s-game { stroke: var(--seek-fur); }
.f-game-light { fill: color-mix(in oklab, var(--seek-fur), white 45%); }
.f-ink { fill: #4d4d4d; }

/* Only the current mood shows, its two frames taking turns. */
.frame { visibility: hidden; }
.marker[data-mode='play'] .play .f1,
.marker[data-mode='pause'] .pause .f1,
.marker[data-mode='seek'] .seek .f1 { visibility: visible; animation: first calc(2 * var(--seek-frame)) steps(1) infinite; }
.marker[data-mode='play'] .play .f2,
.marker[data-mode='pause'] .pause .f2,
.marker[data-mode='seek'] .seek .f2 { animation: second calc(2 * var(--seek-frame)) steps(1) infinite; }
@keyframes first { 50% { visibility: hidden; } }
@keyframes second { 50% { visibility: visible; } }
@media (prefers-reduced-motion: reduce) {
  .frame { animation: none !important; }
}
</style>
